// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadCaveat = makeLoadFont('Caveat');

const { fontFamily: interFamily } = loadInter();
const { fontFamily: caveatFamily } = loadCaveat();



export type JudgesScoreCardProps = Record<string, any>;

const JudgesScoreCard: React.FC<JudgesScoreCardProps> = ({
  backgroundColor = "#e2e8f0",
  transparentBackground = false,
  durationInSeconds = 20,
  cardColor = "#ffffff",
  headerBackgroundColor = "#0f172a",
  textColor = "#1e293b",
  accentColor = "#3b82f6",
  title = "OFFICIAL EVALUATION",
  maxScore = 5,
  rows = [
    { label: "Business Idea", reportScore: 4.5, interviewScore: 4.0, presentationScore: 5.0 },
    { label: "Business Operations", reportScore: 4.0, interviewScore: 4.2, presentationScore: 4.5 },
    { label: "Marketing & Customer Engagement", reportScore: 4.8, interviewScore: 4.5, presentationScore: 4.8 },
    { label: "Teamwork & Problem Solving", reportScore: 4.5, interviewScore: 4.0, presentationScore: 4.5 },
    { label: "Learning & Reflection", reportScore: 4.0, interviewScore: 4.0, presentationScore: 4.0 },
    { label: "Goals, Effort & Achievement", reportScore: 4.5, interviewScore: 4.5, presentationScore: 4.5 },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const totalFrames = fps * durationInSeconds;

  // Layout calculations
  const cw = 1600; 
  const ch = 860;  
  const cx = (width - cw) / 2;
  const cy = (height - ch) / 2;

  const headerH = 120;
  const tableHeaderH = 60;
  const rowH = 90;
  const totalRowH = 100;
  const colWidth = 220;

  type ActionType = "write" | "circle";
  const cellsBase: Array<{ rIndex: number; cIndex: number; score: number; type: ActionType }> = [];
  
  rows.forEach((r, i) => {
    cellsBase.push({ rIndex: i, cIndex: 0, score: r.reportScore, type: "write" });
    cellsBase.push({ rIndex: i, cIndex: 1, score: r.interviewScore, type: "write" });
    cellsBase.push({ rIndex: i, cIndex: 2, score: r.presentationScore, type: "write" });
    cellsBase.push({ rIndex: i, cIndex: 2, score: r.presentationScore, type: "circle" });
  });

  const tEnter = totalFrames * 0.1;
  const tExit = totalFrames * 0.92;
  const writingDuration = tExit - tEnter;
  const timePerAction = writingDuration / cellsBase.length;

  const contentStartY = cy + headerH + tableHeaderH;
  const getColX = (cIndex: number) => cx + cw - 80 - (3 - cIndex) * colWidth + colWidth / 2;

  // Build cells array with precise timing and geometric paths
  const cellsWithTiming = cellsBase.map((c, i) => {
    const start = tEnter + i * timePerAction;
    const end = start + timePerAction * 0.6; // 60% action, 40% travel
    const yCenter = contentStartY + c.rIndex * rowH + rowH / 2;
    const xCenter = getColX(c.cIndex);

    let xEnter = 0, yEnter = 0, xExit = 0, yExit = 0;

    if (c.type === "write") {
      xEnter = xCenter - 30;
      yEnter = yCenter;
      xExit = xCenter + 30;
      yExit = yCenter;
    } else {
      const startAngle = -Math.PI / 2;
      const endAngle = startAngle + Math.PI * 2.2;
      xEnter = xCenter + Math.cos(startAngle) * 45;
      yEnter = yCenter + Math.sin(startAngle) * 35;
      xExit = xCenter + Math.cos(endAngle) * 45;
      yExit = yCenter + Math.sin(endAngle) * 35;
    }

    return { 
      ...c, start, end, xCenter, yCenter, xEnter, yEnter, xExit, yExit 
    };
  });

  // Generate deterministic points for the SVG circle path
  const circlePoints = useMemo(() => {
    const pts = [];
    const steps = 40;
    for (let s = 0; s <= steps; s++) {
      const prog = s / steps;
      const a = -Math.PI / 2 + prog * (Math.PI * 2.2);
      const px = Math.cos(a) * 45;
      const py = Math.sin(a) * 35;
      pts.push(`${px.toFixed(2)},${py.toFixed(2)}`);
    }
    return pts.join(" ");
  }, []);

  // Card Intro Animation
  const cardScale = spring({ frame, fps, config: { damping: 14 } });
  const cardOpacity = interpolate(frame, [0, 15], [0, 1], { extrapolateRight: "clamp" });

  // --- PENCIL ANIMATION LOGIC ---
  let px = width + 500;
  let py = height + 500;
  let env = 0; // Wiggle activity

  if (frame < tEnter) {
    px = interpolate(frame, [0, tEnter], [width + 500, cellsWithTiming[0].xEnter], { extrapolateRight: "clamp" });
    py = interpolate(frame, [0, tEnter], [cellsWithTiming[0].yEnter - 300, cellsWithTiming[0].yEnter], { extrapolateRight: "clamp" });
  } else if (frame > tExit) {
    const lastCell = cellsWithTiming[cellsWithTiming.length - 1];
    px = interpolate(frame, [tExit, totalFrames], [lastCell.xExit, width + 500], { extrapolateLeft: "clamp" });
    py = interpolate(frame, [tExit, totalFrames], [lastCell.yExit, height + 500], { extrapolateLeft: "clamp" });
  } else {
    for (let i = 0; i < cellsWithTiming.length; i++) {
      const c = cellsWithTiming[i];
      const nextC = cellsWithTiming[i + 1];

      if (frame >= c.start && frame <= c.end) {
        const prog = interpolate(frame, [c.start, c.end], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
        if (c.type === "write") {
          px = c.xEnter + prog * (c.xExit - c.xEnter);
          py = c.yCenter;
          env = interpolate(frame, [c.start, c.start + 2, c.end - 2, c.end], [0, 1, 1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
        } else {
          const angle = -Math.PI / 2 + prog * (Math.PI * 2.2);
          px = c.xCenter + Math.cos(angle) * 45;
          py = c.yCenter + Math.sin(angle) * 35;
          env = 0; // Smooth circle
        }
        break;
      } else if (nextC && frame > c.end && frame < nextC.start) {
        const travelProg = interpolate(frame, [c.end, nextC.start], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
        px = interpolate(travelProg, [0, 1], [c.xExit, nextC.xEnter]);
        const liftAmt = c.rIndex !== nextC.rIndex ? -40 : -15; 
        const lift = Math.sin(travelProg * Math.PI) * liftAmt; 
        py = interpolate(travelProg, [0, 1], [c.yExit, nextC.yEnter]) + lift;
        break;
      } else if (!nextC && frame > c.end) {
        px = c.xExit;
        py = c.yExit;
      }
    }
  }

  const zigzagX = Math.sin(frame * 6) * 6 * env;
  const zigzagY = Math.cos(frame * 8) * 8 * env;
  const finalPx = px + zigzagX;
  const finalPy = py + zigzagY;
  const pencilRot = -35 + (Math.sin(frame * 4) * 8 * env);

  // --- TOTAL CALCULATION ---
  const totalScoreValue = rows.reduce((sum, r) => sum + r.presentationScore, 0);
  const totalScore = totalScoreValue.toFixed(1);
  const maxTotal = maxScore * rows.length;
  const totalRevealFrame = cellsWithTiming[cellsWithTiming.length - 1].end + 10;
  
  const totalScale = spring({
    frame: frame - totalRevealFrame,
    fps,
    config: { stiffness: 200, damping: 12 },
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      <div style={{
        position: "absolute",
        width: "150%",
        height: "150%",
        top: "-25%",
        left: "-25%",
        background: `radial-gradient(circle at 50% 50%, ${accentColor}15 0%, transparent 60%)`,
        opacity: interpolate(frame, [0, 60], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" })
      }} />

      <div style={{
        position: "absolute",
        left: cx,
        top: cy,
        width: cw,
        height: ch,
        backgroundColor: cardColor,
        borderRadius: "24px",
        boxShadow: "0 30px 60px -15px rgba(0,0,0,0.15), 0 15px 25px -10px rgba(0,0,0,0.1)",
        transform: `scale(${cardScale})`,
        opacity: cardOpacity,
        overflow: "hidden",
      }}>
        {/* Header */}
        <div style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: "100%",
          height: headerH,
          backgroundColor: headerBackgroundColor,
          display: "flex",
          alignItems: "center",
          padding: "0 80px",
          color: cardColor,
          justifyContent: "space-between"
        }}>
          <h1 style={{ fontSize: "48px", fontWeight: 800, margin: 0, letterSpacing: "2px" }}>
            {title}
          </h1>
          <div style={{ fontSize: "20px", fontWeight: 500, opacity: 0.8, border: `2px solid ${cardColor}`, padding: "8px 16px", borderRadius: "10px" }}>
            CONFIDENTIAL
          </div>
        </div>

        {/* Table Headers */}
        <div style={{
          position: "absolute",
          top: headerH,
          left: 0,
          width: "100%",
          height: tableHeaderH,
          display: "flex",
          padding: "0 80px",
          alignItems: "center",
          borderBottom: `2px solid ${textColor}15`,
          color: `${textColor}80`,
          fontSize: "18px",
          fontWeight: 700,
          letterSpacing: "1px"
        }}>
          <div style={{ flex: 1 }}>EVALUATION CATEGORY</div>
          <div style={{ width: `${colWidth}px`, textAlign: "center", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center" }}>
            <span>REPORT</span>
            <span style={{ fontSize: "12px", fontWeight: 600, opacity: 0.6, marginTop: "2px" }}>OUT OF {maxScore}</span>
          </div>
          <div style={{ width: `${colWidth}px`, textAlign: "center", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center" }}>
            <span>INTERVIEW</span>
            <span style={{ fontSize: "12px", fontWeight: 600, opacity: 0.6, marginTop: "2px" }}>OUT OF {maxScore}</span>
          </div>
          <div style={{ width: `${colWidth}px`, textAlign: "center", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center" }}>
            <span>PRESENTATION</span>
            <span style={{ fontSize: "12px", fontWeight: 600, opacity: 0.6, marginTop: "2px" }}>OUT OF {maxScore}</span>
          </div>
        </div>

        {/* Row Elements */}
        {rows.map((item, i) => {
          const localY = headerH + tableHeaderH + i * rowH;
          
          const rowEntrance = spring({
            frame: frame - (10 + i * 4),
            fps,
            config: { damping: 14 }
          });

          // Fetch animation timing blocks for this specific row
          const reportCell = cellsWithTiming.find(c => c.rIndex === i && c.cIndex === 0);
          const interviewCell = cellsWithTiming.find(c => c.rIndex === i && c.cIndex === 1);
          const presentationCell = cellsWithTiming.find(c => c.rIndex === i && c.cIndex === 2 && c.type === "write");
          const circleCell = cellsWithTiming.find(c => c.rIndex === i && c.cIndex === 2 && c.type === "circle");

          const reportReveal = reportCell ? interpolate(frame, [reportCell.start, reportCell.end], [0, 100], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }) : 0;
          const interviewReveal = interviewCell ? interpolate(frame, [interviewCell.start, interviewCell.end], [0, 100], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }) : 0;
          const presentationReveal = presentationCell ? interpolate(frame, [presentationCell.start, presentationCell.end], [0, 100], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }) : 0;
          const circleReveal = circleCell ? interpolate(frame, [circleCell.start, circleCell.end], [0, 100], { extrapolateLeft: "clamp", extrapolateRight: "clamp" }) : 0;

          return (
            <div key={item.label + i} style={{
              position: "absolute",
              top: localY,
              left: 0,
              width: "100%",
              height: rowH,
              display: "flex",
              alignItems: "center",
              padding: "0 80px",
              borderBottom: i < rows.length - 1 ? `1px solid ${textColor}10` : "none",
              opacity: rowEntrance,
              transform: `translateY(${(1 - rowEntrance) * 15}px)`,
            }}>
              <div style={{ flex: 1, fontSize: "28px", fontWeight: 600, color: textColor }}>
                {item.label}
              </div>

              {/* Score 0: Report */}
              <div style={{ width: `${colWidth}px`, display: "flex", justifyContent: "center", position: "relative" }}>
                <div style={{
                  fontFamily: caveatFamily,
                  fontSize: "48px",
                  fontWeight: 700,
                  color: accentColor,
                  clipPath: `inset(0 ${100 - reportReveal}% 0 0)`,
                  lineHeight: 1,
                  whiteSpace: "nowrap",
                  paddingBottom: "8px"
                }}>
                  {item.reportScore.toFixed(1)}
                </div>
              </div>

              {/* Score 1: Interview */}
              <div style={{ width: `${colWidth}px`, display: "flex", justifyContent: "center", position: "relative" }}>
                <div style={{
                  fontFamily: caveatFamily,
                  fontSize: "48px",
                  fontWeight: 700,
                  color: accentColor,
                  clipPath: `inset(0 ${100 - interviewReveal}% 0 0)`,
                  lineHeight: 1,
                  whiteSpace: "nowrap",
                  paddingBottom: "8px"
                }}>
                  {item.interviewScore.toFixed(1)}
                </div>
              </div>

              {/* Score 2: Presentation & Circle */}
              <div style={{ width: `${colWidth}px`, display: "flex", justifyContent: "center", position: "relative" }}>
                <div style={{
                  fontFamily: caveatFamily,
                  fontSize: "48px",
                  fontWeight: 700,
                  color: accentColor,
                  clipPath: `inset(0 ${100 - presentationReveal}% 0 0)`,
                  lineHeight: 1,
                  whiteSpace: "nowrap",
                  paddingBottom: "8px",
                  position: "relative",
                  zIndex: 2
                }}>
                  {item.presentationScore.toFixed(1)}
                </div>
                {circleReveal > 0 && (
                  <svg 
                    width="120" 
                    height="120" 
                    viewBox="-60 -60 120 120" 
                    style={{ 
                      position: 'absolute', 
                      top: '50%', 
                      left: '50%', 
                      transform: 'translate(-50%, -50%)', 
                      pointerEvents: 'none',
                      zIndex: 1
                    }}
                  >
                    <polyline 
                      points={circlePoints} 
                      fill="none" 
                      stroke={accentColor} 
                      strokeWidth={4} 
                      strokeDasharray={100} 
                      strokeDashoffset={100 - circleReveal} 
                      pathLength={100} 
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    />
                  </svg>
                )}
              </div>
            </div>
          );
        })}

        {/* Total Row */}
        <div style={{
          position: "absolute",
          top: ch - totalRowH - 20, 
          left: 80,
          right: 80,
          height: totalRowH,
          display: "flex",
          alignItems: "center",
          padding: "0 30px",
          borderTop: `4px solid ${textColor}`,
          backgroundColor: `${accentColor}08`,
          borderRadius: "16px",
          opacity: totalScale,
          transform: `scale(${interpolate(totalScale, [0, 1], [0.95, 1])})`,
        }}>
          <div style={{ flex: 1, fontSize: "36px", fontWeight: 800, color: textColor }}>
            FINAL TOTAL
          </div>
          <div style={{
            fontFamily: caveatFamily,
            fontSize: "64px",
            fontWeight: 700,
            color: textColor,
            lineHeight: 1
          }}>
            {totalScore} <span style={{ fontSize: "36px", color: `${textColor}60` }}>/ {maxTotal}</span>
          </div>
        </div>
      </div>

      {/* The Pencil SVG */}
      <div style={{
        position: "absolute",
        left: finalPx,
        top: finalPy,
        width: 0,
        height: 0,
        zIndex: 100,
        filter: "drop-shadow(10px 20px 15px rgba(0,0,0,0.3))",
      }}>
        <svg
          width="120"
          height="300"
          viewBox="-60 -280 120 300"
          style={{
            position: "absolute",
            left: -60, 
            top: -280, 
            transformOrigin: "60px 280px", 
            transform: `rotate(${pencilRot}deg)`,
            overflow: "visible"
          }}
        >
          {/* Tip / Graphite */}
          <polygon points="0,0 8,-25 -8,-25" fill="#333" />
          {/* Wood Cone */}
          <polygon points="8,-25 -8,-25 -18,-60 18,-60" fill="#e2c296" />
          {/* Main Body */}
          <rect x="-18" y="-220" width="36" height="160" fill="#fbbf24" />
          {/* Body Lines for 3D effect */}
          <rect x="-6" y="-220" width="12" height="160" fill="#f59e0b" />
          {/* Metal Band */}
          <rect x="-19" y="-245" width="38" height="25" fill="#9ca3af" />
          <rect x="-19" y="-240" width="38" height="4" fill="#6b7280" />
          <rect x="-19" y="-230" width="38" height="4" fill="#6b7280" />
          {/* Eraser */}
          <rect x="-18" y="-270" width="36" height="25" rx="8" fill="#f472b6" />
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default JudgesScoreCard;